-- Batch 03: independently cross-checked public building sources. Two current evidence rows per field, one audit and one evidence group.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
SET LOCAL application_name='colliers_ai_backfill_20261125_v6';
DO $fill$
DECLARE r record; n int:=0; old_count int; changed int; ev uuid; now_ts timestamptz; read_value jsonb; sub_batch int:=3; expected_before int:=45; expected_added int:=21;
BEGIN
 PERFORM pg_advisory_xact_lock(hashtext('ai_building_field_backfill_20261125_v6_100'));
 SELECT count(*) INTO old_count FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v6_100';
 IF old_count<>expected_before OR old_count+expected_added>100 THEN RAISE EXCEPTION 'batch sequence guard: %',old_count; END IF;
 LOCK TABLE public.buildings,public.building_brochure_data,public.building_data_field_provenance IN SHARE ROW EXCLUSIVE MODE;
 FOR r IN
 WITH specs AS (SELECT * FROM jsonb_to_recordset($ext$[{"id":"06c23ea0-a545-446c-84da-75dccb99a231","f":"gfa_total","type":"numeric","value":71000,"unit":"m2","sources":[{"url":"https://www.huarundasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://fdc.fang.com/news/2020-11-29/37867325.htm","name":"房天下产业网2020-11-29市场报告","tier":"secondary"}],"note":"同址建国门北大街8号；招商资料约71000㎡，房天下71054㎡，按共同千平方米精度取约数"},{"id":"06c23ea0-a545-446c-84da-75dccb99a231","f":"parking_above","type":"integer","value":110,"unit":"count","sources":[{"url":"https://www.huarundasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://fdc.fang.com/news/2020-11-29/37867325.htm","name":"房天下产业网2020-11-29市场报告","tier":"secondary"}],"note":"同址历史地上车位110；其他资料地下口径不一，未填地下和总数"},{"id":"06c23ea0-a545-446c-84da-75dccb99a231","f":"clear_height","type":"numeric","value":2.65,"unit":"m","sources":[{"url":"https://www.huarundasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://www.office-beijing.com/office/1527.html","name":"北京写字楼门户","tier":"secondary"}],"note":"同址办公标准净高2.65m；不采用层高口径"},{"id":"06c23ea0-a545-446c-84da-75dccb99a231","f":"elevator_freight","type":"integer","value":4,"unit":"count","sources":[{"url":"https://www.huarundasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://www.fffzu.com/62/","name":"北京办公选址","tier":"secondary"}],"note":"同址公开招商资料货梯4部，历史配置"},{"id":"2e4f2d26-5304-4d88-b588-65bcbbd43bb9","f":"parking_above","type":"integer","value":20,"unit":"count","sources":[{"url":"https://wap.centanet.com/bj/xiezilou/chuzu/bjxzl71524.html","name":"中原地产","tier":"secondary"},{"url":"https://cj.sina.com.cn/articles/view/2664057621/9eca4b15020010hv0","name":"房天下2023-07报告（新浪转载）","tier":"secondary"}],"note":"东直门南大街甲3号；中原与房天下均列地上20、地下283，合计303；历史招商参数"},{"id":"2e4f2d26-5304-4d88-b588-65bcbbd43bb9","f":"parking_underground","type":"integer","value":283,"unit":"count","sources":[{"url":"https://wap.centanet.com/bj/xiezilou/chuzu/bjxzl71524.html","name":"中原地产","tier":"secondary"},{"url":"https://cj.sina.com.cn/articles/view/2664057621/9eca4b15020010hv0","name":"房天下2023-07报告（新浪转载）","tier":"secondary"}],"note":"东直门南大街甲3号；中原与房天下均列地上20、地下283，合计303；历史招商参数"},{"id":"2e4f2d26-5304-4d88-b588-65bcbbd43bb9","f":"parking_total","type":"integer","value":303,"unit":"count","sources":[{"url":"https://wap.centanet.com/bj/xiezilou/chuzu/bjxzl71524.html","name":"中原地产","tier":"secondary"},{"url":"https://cj.sina.com.cn/articles/view/2664057621/9eca4b15020010hv0","name":"房天下2023-07报告（新浪转载）","tier":"secondary"}],"note":"东直门南大街甲3号；中原与房天下均列地上20、地下283，合计303；历史招商参数"},{"id":"2e4f2d26-5304-4d88-b588-65bcbbd43bb9","f":"floors_below","type":"integer","value":3,"unit":"floor","sources":[{"url":"https://www.jurandasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://wap.centanet.com/bj/xiezilou/chuzu/bjxzl71524.html","name":"中原地产","tier":"secondary"}],"note":"两源明确地下3层；地上17/18层口径不一未填"},{"id":"2e4f2d26-5304-4d88-b588-65bcbbd43bb9","f":"elevator_passenger","type":"integer","value":8,"unit":"count","sources":[{"url":"https://www.jurandasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://www.office-beijing.com/office/539.html","name":"北京写字楼门户","tier":"secondary"}],"note":"同址两份公开招商资料均区分客梯8、货梯2，中原合计10"},{"id":"2e4f2d26-5304-4d88-b588-65bcbbd43bb9","f":"elevator_freight","type":"integer","value":2,"unit":"count","sources":[{"url":"https://www.jurandasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://www.office-beijing.com/office/539.html","name":"北京写字楼门户","tier":"secondary"}],"note":"同址两份公开招商资料均区分客梯8、货梯2，中原合计10"},{"id":"2e4f2d26-5304-4d88-b588-65bcbbd43bb9","f":"hvac_system","type":"text","value":"集中式中央空调","unit":"configuration","sources":[{"url":"https://www.jurandasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://www.office-beijing.com/office/539.html","name":"北京写字楼门户","tier":"secondary"}],"note":"同址资料对外招商项目配置及办公建筑面积（约数）；等级是公开定位而非市场分类"},{"id":"2e4f2d26-5304-4d88-b588-65bcbbd43bb9","f":"facade_type","type":"text","value":"玻璃幕墙","unit":"configuration","sources":[{"url":"https://www.jurandasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://www.office-beijing.com/office/539.html","name":"北京写字楼门户","tier":"secondary"}],"note":"同址资料对外招商项目配置及办公建筑面积（约数）；等级是公开定位而非市场分类"},{"id":"2e4f2d26-5304-4d88-b588-65bcbbd43bb9","f":"grade","type":"text","value":"甲级","unit":"brochure_positioning","sources":[{"url":"https://www.jurandasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://www.office-beijing.com/office/539.html","name":"北京写字楼门户","tier":"secondary"}],"note":"同址资料对外招商项目配置及办公建筑面积（约数）；等级是公开定位而非市场分类"},{"id":"2e4f2d26-5304-4d88-b588-65bcbbd43bb9","f":"gfa_office","type":"numeric","value":33000,"unit":"m2","sources":[{"url":"https://www.jurandasha.cn/","name":"北京写字楼信息网","tier":"secondary"},{"url":"https://www.office-beijing.com/office/539.html","name":"北京写字楼门户","tier":"secondary"}],"note":"同址资料对外招商项目配置及办公建筑面积（约数）；等级是公开定位而非市场分类"},{"id":"8fb2932d-d3cc-41bf-99dd-8adcc46c5302","f":"floors_above","type":"integer","value":16,"unit":"floor","sources":[{"url":"https://office-beijing.com/office/218.html","name":"北京写字楼门户","tier":"secondary"},{"url":"https://m.mingdefang.cn/beijingshi/zufang/295.html","name":"明德房产","tier":"secondary"}],"note":"北辰东路8号；两源明确地上16地下2，使用率70%；不改原系统记录楼层"},{"id":"8fb2932d-d3cc-41bf-99dd-8adcc46c5302","f":"floors_below","type":"integer","value":2,"unit":"floor","sources":[{"url":"https://office-beijing.com/office/218.html","name":"北京写字楼门户","tier":"secondary"},{"url":"https://m.mingdefang.cn/beijingshi/zufang/295.html","name":"明德房产","tier":"secondary"}],"note":"北辰东路8号；两源明确地上16地下2，使用率70%；不改原系统记录楼层"},{"id":"8fb2932d-d3cc-41bf-99dd-8adcc46c5302","f":"efficiency_rate","type":"numeric","value":70,"unit":"percent","sources":[{"url":"https://office-beijing.com/office/218.html","name":"北京写字楼门户","tier":"secondary"},{"url":"https://m.mingdefang.cn/beijingshi/zufang/295.html","name":"明德房产","tier":"secondary"}],"note":"北辰东路8号；两源明确地上16地下2，使用率70%；不改原系统记录楼层"},{"id":"8fb2932d-d3cc-41bf-99dd-8adcc46c5302","f":"developer","type":"text","value":"北京北辰房地产开发有限公司","unit":"company","sources":[{"url":"https://office-beijing.com/office/218.html","name":"北京写字楼门户","tier":"secondary"},{"url":"https://www.xzlsd.com/office_detail/826.html","name":"首都写字楼出租网","tier":"secondary"}],"note":"同址项目，两个参数表列相同开发企业名；不推断业主"},{"id":"8fb2932d-d3cc-41bf-99dd-8adcc46c5302","f":"hvac_system","type":"text","value":"集中式中央空调","unit":"configuration","sources":[{"url":"https://www.xzlsd.com/office_detail/826.html","name":"首都写字楼出租网","tier":"secondary"},{"url":"https://m.mingdefang.cn/beijingshi/zufang/295.html","name":"明德房产","tier":"secondary"}],"note":"同址，两源均明确集中式中央空调，具体末端制式未填"},{"id":"fd725dbc-703d-4fec-90b5-86a08b180d17","f":"hvac_system","type":"text","value":"集中式中央空调","unit":"configuration","sources":[{"url":"https://www.juduolou.com/loupan/details-6576471.html","name":"聚多楼","tier":"secondary"},{"url":"https://www.fffzu.com/3/","name":"北京办公选址","tier":"secondary"}],"note":"霄云路40号同一项目；招商资料共同支持中央空调及甲级公开定位，具体制式不填"},{"id":"fd725dbc-703d-4fec-90b5-86a08b180d17","f":"grade","type":"text","value":"甲级","unit":"brochure_positioning","sources":[{"url":"https://www.juduolou.com/loupan/details-6576471.html","name":"聚多楼","tier":"secondary"},{"url":"https://www.fffzu.com/3/","name":"北京办公选址","tier":"secondary"}],"note":"霄云路40号同一项目；招商资料共同支持中央空调及甲级公开定位，具体制式不填"}]$ext$::jsonb) v(id uuid,f text,type text,value jsonb,unit text,sources jsonb,note text)) SELECT b.id bid,b.name,d.id target_id,v.f field_name,v.value new_value,v.type value_type,v.unit,v.sources,v.note FROM specs v JOIN building_brochure_data d ON d.id=v.id JOIN buildings b ON b.id=d.building_id WHERE b.is_active AND b.city IN ('北京','北京市') AND b.tracking_scope='tracked' AND b.project_type='stock' AND b.merged_into_id IS NULL AND (SELECT count(*) FROM building_brochure_data q WHERE q.building_id=b.id)=1 AND to_jsonb(d)->v.f='null'::jsonb AND (SELECT count(distinct substring(s->>'url' from 'https?://([^/]+)')) FROM jsonb_array_elements(v.sources) s)>=2 AND NOT EXISTS(SELECT 1 FROM building_data_field_provenance p WHERE p.building_id=b.id AND p.target_table='building_brochure_data' AND p.field_name=v.f) AND NOT EXISTS(SELECT 1 FROM audit_logs a WHERE a.action_type='AI_FIELD_FILL' AND a.target_table='building_brochure_data' AND a.target_id=d.id::text AND (a.details->>'field_name'=v.f OR a.new_values ? v.f)) ORDER BY target_id,field_name
 LOOP
  IF r.new_value IS NULL OR r.new_value='null'::jsonb OR r.value_type NOT IN ('text','integer','numeric','boolean','date') THEN RAISE EXCEPTION 'invalid candidate'; END IF;
  ev:=gen_random_uuid(); now_ts:=clock_timestamp();
  EXECUTE format('UPDATE public.building_brochure_data SET %I=($2#>>''{}'')::%s WHERE id=$1 AND building_id=$3 AND %I IS NULL',r.field_name,r.value_type,r.field_name) USING r.target_id,r.new_value,r.bid;
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>1 THEN RAISE EXCEPTION 'null protection failed'; END IF;
  INSERT INTO public.building_data_field_provenance(building_id,brochure_data_id,target_table,field_name,field_value,source_type,source_tier,source_name,source_url,source_retrieved_at,value_recorded_at,verification_status,evidence_group_id,evidence_note,is_current)
  SELECT r.bid,r.target_id,'building_brochure_data',r.field_name,r.new_value,'internet',e->>'tier',e->>'name',e->>'url',now_ts,now_ts,'cross_verified',ev,'batch_ref=ai_building_field_backfill_20261125_v6_100; unit='||r.unit||'; '||r.note||'; AI-assisted',true FROM jsonb_array_elements(r.sources) e;
  GET DIAGNOSTICS changed=ROW_COUNT; IF changed<>jsonb_array_length(r.sources) OR changed<2 THEN RAISE EXCEPTION 'source count mismatch'; END IF;
  INSERT INTO public.audit_logs(id,user_id,action_type,details,request_source,module,target_table,target_id,target_name,old_values,new_values,event_id,occurred_at,actor_kind,actor_name)
  VALUES(nextval('public.audit_logs_id_seq'),'codex','AI_FIELD_FILL',jsonb_build_object('batch_ref','ai_building_field_backfill_20261125_v6_100','sub_batch',sub_batch,'building_id',r.bid,'field_name',r.field_name,'source_kind','external_cross_verified','source_urls',r.sources,'unit',r.unit,'verification_status','cross_verified','evidence_group_id',ev,'ai_assisted',true,'reversible',true),'codex_mcp','building_brochure_data','building_brochure_data',r.target_id::text,r.name,jsonb_build_object(r.field_name,NULL),jsonb_build_object(r.field_name,r.new_value),'ai_field_fill:'||ev::text,now_ts,'tool','Codex（工具执行）');
  EXECUTE format('SELECT to_jsonb(%I) FROM public.building_brochure_data WHERE id=$1',r.field_name) INTO read_value USING r.target_id;
  IF read_value IS DISTINCT FROM r.new_value OR (SELECT count(*) FROM public.building_data_field_provenance p WHERE p.evidence_group_id=ev AND p.is_current AND p.field_value=read_value)<>jsonb_array_length(r.sources) OR NOT EXISTS(SELECT 1 FROM public.audit_logs a WHERE a.event_id='ai_field_fill:'||ev::text AND a.new_values->r.field_name=read_value AND a.old_values->r.field_name='null'::jsonb) THEN RAISE EXCEPTION 'readback failed'; END IF;
  n:=n+1;
 END LOOP;
 IF n<>expected_added THEN RAISE EXCEPTION 'expected %, got %',expected_added,n; END IF;
END $fill$;
SELECT count(*) cumulative,count(distinct (target_table,target_id,details->>'field_name')) unique_fields FROM public.audit_logs WHERE action_type='AI_FIELD_FILL' AND details->>'batch_ref'='ai_building_field_backfill_20261125_v6_100';
COMMIT;